ANDROID_FILES = {'README.md': '# PersonaChat — offline character chat (llama.cpp on Android)\n\nA complete Android chat app that runs LLMs **fully on-device** via llama.cpp (JNI):\ncreate characters, chat with them with streaming replies, and rewrite any character\ncard with a plain-English prompt processed by the local model. No accounts, no cloud,\nno network calls for inference — the app adds no filtering layer; behavior is whatever\nthe GGUF model you load produces.\n\n## Features\n- **Model screen**: list `.gguf` files in the private files dir, download a GGUF from a URL with progress, load/unload, context-size slider.\n- **Characters**: name, emoji avatar, persona, scenario, greeting, example dialogue; JSON persistence per character.\n- **Chat**: streaming token output, stop/clear, uses the model\'s built-in chat template (`llama_chat_apply_template`) with a plain-format fallback.\n- **AI Modify**: meta-prompt asks the local model to rewrite the card inside `<<<JSON>>>...<<<END>>>` markers; parsed and previewed before applying.\n- JNI bridge (`llama-android.cpp`) uses the modern C API: `llama_model_load_from_file`, sampler chains, flash attention, naive context shift.\n\n## Build\n1. Install Android Studio (Hedgehog+), Android SDK 34, NDK (Side by Side) and CMake 3.22.1 from the SDK Manager.\n2. Clone/fetch llama.cpp sources:\n   ```bash\n   ./scripts/fetch_llama_cpp.sh        # or: git clone https://github.com/ggml-org/llama.cpp app/src/main/cpp/llama.cpp\n   ```\n3. Open the project in Android Studio, let Gradle sync (wrapper jar will be generated; CLI: `gradle wrapper` first).\n4. Build & run on an ARM64 device/emulator (x86_64 works but is slow).\n5. Get a GGUF model — three ways, pick one (details below):\n   - **In-app download** (easiest): paste a direct URL on the Models screen, tap Download.\n   - **Download on PC, push via adb** (faster/reliable for big files).\n   - **Download on the phone** with a browser/HF app and copy into the files dir.\n\n## Getting a GGUF model\n\nModels must be single-file `.gguf` (instruct/chat fine-tunes work best — the app uses the\nmodel\'s built-in chat template when present). On a phone, stay small: **1–4B params**,\nquant **Q4_K_M** by default (drop to Q3_K_M / IQ4_XS on low-RAM devices; Q6_K/Q8_0 if you\nhave 8GB+ RAM). Rule of thumb: model file size + ~1GB for context overhead must fit in RAM.\n\n### Option A — built-in Hugging Face browser (easiest)\nThe Models screen has a **Browse Hugging Face (GGUF)** search box — it queries the public\nHugging Face Hub API (no key needed), shows results sorted by downloads, and tapping a\nrepo lists its loadable `.gguf` files with sizes. Tap **Get** to download straight into\nthe app. Split shard files (`...-00001-of-00002.gguf`) are filtered out automatically.\nYou can still paste a direct URL manually below it.\n\n### Option A — in-app downloader\n1. Find a GGUF on Hugging Face (search a model + "GGUF"; `bartowski` and `unsloth` repos are\n   reliable quantizations).\n2. Open the file\'s page → click the download arrow → **copy the direct link** (a\n   `.../resolve/main/<file>.gguf` URL).\n3. Paste it into "GGUF download URL" on the app\'s Models screen → Download. The file lands\n   directly in the app\'s private files dir and appears in the list → tap **Load**.\n\nExample direct URL (Qwen3 1.7B, ~1.3GB — good first test):\n```\nhttps://huggingface.co/bartowski/Qwen_Qwen3-1.7B-GGUF/resolve/main/Qwen3-1.7B-Q4_K_M.gguf\n```\nNote: these URLs redirect; the app\'s downloader follows redirects, but the *first* hop must\nbe the file. If a download fails, use Option B.\n\n### Option B — PC download + adb (recommended for files >2GB)\n```bash\n# on your PC (or: click the file on huggingface.co and download via browser)\nhuggingface-cli download bartowski/Qwen_Qwen3-1.7B-GGUF \\\n  --include "Qwen3-1.7B-Q4_K_M.gguf" --local-dir .\n\n# push to the device, then move it into the app\'s private files dir\n# (works with the debug build; \'run-as\' requires the app to be debuggable)\nadb push Qwen3-1.7B-Q4_K_M.gguf /data/local/tmp/\nadb shell run-as com.personachat cp /data/local/tmp/Qwen3-1.7B-Q4_K_M.gguf files/\n```\nThen open the app → Models → **Rescan** → Load.\n\n### Option C — on-device download\nDownload the `.gguf` in the phone\'s browser (Files/Downloads), then either use the app\'s\ndownloader instead, or with a rooted device copy it to\n`/data/data/com.personachat/files/`. Without root, Option A is the equivalent path —\nbrowsers can\'t write into another app\'s private dir.\n\n### Verifying the file\nThe Models screen shows file size — compare it with the size listed on the Hugging Face page.\nA truncated download will fail at load time with `failed to load model` in logcat\n(`adb logcat -s persona-jni`); just re-download. Also avoid *split* GGUFs\n(`...-00001-of-00002.gguf`) — the app loads single files only.\n\n## Notes / caveats\n- CPU-only by default (`n_gpu_layers = 0`); wire up Vulkan/OpenCL in llama.cpp\'s CMake if you want GPU offload.\n- First token latency and speed depend entirely on the model size and device RAM. 4096 ctx ≈ a few hundred MB extra for KV on small models.\n- llama.cpp renames C API symbols occasionally. If NDK build fails on a missing symbol, open the checked-out `llama.h` and adjust `llama-android.cpp` (single place).\n- History is trimmed to ~6k chars before prompting; the JNI side truncates/shifts if the context fills mid-generation.\n- "No restrictions" here means: offline, private, no server-side anything. The app doesn\'t censor prompts, but it also doesn\'t include a safety-bypass/jailbreak module — what a given model will or won\'t generate depends on the model file you load.\n', 'build.gradle.kts': 'plugins {\n    id("com.android.application") version "8.5.2" apply false\n    id("org.jetbrains.kotlin.android") version "1.9.24" apply false\n    id("org.jetbrains.kotlin.plugin.serialization") version "1.9.24" apply false\n}\n', 'gradle.properties': 'org.gradle.jvmargs=-Xmx4g -Dfile.encoding=UTF-8\nandroid.useAndroidX=true\nandroid.nonTransitiveRClass=true\nkotlin.code.style=official\n', 'settings.gradle.kts': 'pluginManagement {\n    repositories { google(); mavenCentral(); gradlePluginPortal() }\n}\ndependencyResolutionManagement {\n    repositories { google(); mavenCentral() }\n}\nrootProject.name = "PersonaChat"\ninclude(":app")\n', 'app/build.gradle.kts': 'plugins {\n    id("com.android.application")\n    id("org.jetbrains.kotlin.android")\n    id("org.jetbrains.kotlin.plugin.serialization")\n}\n\nandroid {\n    namespace = "com.personachat"\n    compileSdk = 34\n\n    defaultConfig {\n        applicationId = "com.personachat"\n        minSdk = 24\n        targetSdk = 34\n        versionCode = 1\n        versionName = "1.0"\n        externalNativeBuild {\n            cmake { cppFlags("-std=c++17") }\n        }\n    }\n\n    buildTypes {\n        release {\n            isMinifyEnabled = false\n        }\n    }\n    compileOptions {\n        sourceCompatibility = JavaVersion.VERSION_17\n        targetCompatibility = JavaVersion.VERSION_17\n    }\n    kotlinOptions { jvmTarget = "17" }\n    buildFeatures { compose = true }\n    composeOptions { kotlinCompilerExtensionVersion = "1.5.14" }\n    packaging { resources { excludes += "/META-INF/{AL2.0,LGPL2.1}" } }\n    externalNativeBuild {\n        cmake { path = file("src/main/cpp/CMakeLists.txt"); version = "3.22.1" }\n    }\n}\n\ndependencies {\n    implementation(platform("androidx.compose:compose-bom:2024.06.00"))\n    implementation("androidx.compose.ui:ui")\n    implementation("androidx.compose.ui:ui-graphics")\n    implementation("androidx.compose.material3:material3")\n    implementation("androidx.compose.material:material-icons-extended")\n    implementation("androidx.activity:activity-compose:1.9.0")\n    implementation("androidx.navigation:navigation-compose:2.7.7")\n    implementation("androidx.lifecycle:lifecycle-viewmodel-compose:2.7.0")\n    implementation("androidx.lifecycle:lifecycle-runtime-compose:2.7.0")\n    implementation("org.jetbrains.kotlinx:kotlinx-serialization-json:1.6.3")\n}\n', 'app/proguard-rules.pro': '-keep class com.personachat.ai.** { *; }\n', 'scripts/fetch_llama_cpp.sh': '#!/usr/bin/env bash\n# Run from the project root. Fetches llama.cpp into app/src/main/cpp/llama.cpp.\n# llama.cpp changes its C API occasionally; this project was written against the\n# post-b4xxx API (llama_model_load_from_file, llama_sampler_chain, llama_chat_apply_template).\n# If a build error says a symbol is missing, check llama.h at the checked-out commit\n# and rename in app/src/main/cpp/llama-android.cpp.\nset -e\ngit clone --depth 1 https://github.com/ggml-org/llama.cpp app/src/main/cpp/llama.cpp\necho "Done. If CMake config fails, try: git -C app/src/main/cpp/llama.cpp checkout <a release tag>"\n', 'app/src/main/AndroidManifest.xml': '<?xml version="1.0" encoding="utf-8"?>\n<manifest xmlns:android="http://schemas.android.com/apk/res/android">\n\n    <uses-permission android:name="android.permission.INTERNET" />\n\n    <application\n        android:label="PersonaChat"\n        android:theme="@android:style/Theme.Material.NoActionBar"\n        android:allowBackup="true"\n        android:supportsRtl="true">\n        <activity\n            android:name=".MainActivity"\n            android:exported="true"\n            android:windowSoftInputMode="adjustResize"\n            android:configChanges="orientation|screenSize|keyboardHidden">\n            <intent-filter>\n                <action android:name="android.intent.action.MAIN" />\n                <category android:name="android.intent.category.LAUNCHER" />\n            </intent-filter>\n        </activity>\n    </application>\n</manifest>\n', 'app/src/main/cpp/CMakeLists.txt': 'cmake_minimum_required(VERSION 3.22.1)\nproject(persona-jni CXX)\n\nset(CMAKE_CXX_STANDARD 17)\n\n# llama.cpp sources must live here: app/src/main/cpp/llama.cpp\n# (see README: git clone https://github.com/ggml-org/llama.cpp)\nadd_subdirectory(llama.cpp)\n\nadd_library(persona-jni SHARED llama-android.cpp)\n\ntarget_include_directories(persona-jni PRIVATE\n    llama.cpp/include\n    llama.cpp/ggml/include\n)\n\ntarget_link_libraries(persona-jni llama log)\n', 'app/src/main/cpp/llama-android.cpp': '// JNI bridge to llama.cpp for PersonaChat.\n// Written against the modern C API (llama_model_load_from_file / sampler chains /\n// llama_chat_apply_template). llama.cpp moves fast: if a symbol is renamed in a\n// newer checkout, adjust here -- see README "Troubleshooting".\n#include <jni.h>\n#include <string>\n#include <vector>\n#include <cstring>\n#include <cstdlib>\n#include <mutex>\n#include <android/log.h>\n\n#include "llama.h"\n\n#define LOG_TAG "persona-jni"\n#define LOGE(...) __android_log_print(ANDROID_LOG_ERROR, LOG_TAG, __VA_ARGS__)\n\nstatic llama_model   *g_model  = nullptr;\nstatic llama_context *g_ctx    = nullptr;\nstatic const llama_vocab *g_vocab = nullptr;\nstatic int32_t        g_n_ctx  = 4096;\nstatic std::mutex     g_mutex;\nstatic volatile bool  g_stop   = false;\n\nextern "C" {\n\nJNIEXPORT jboolean JNICALL\nJava_com_personachat_ai_LlmEngine_nativeLoadModel(JNIEnv *env, jobject,\n                                                  jstring jpath, jint n_ctx, jint n_threads) {\n    std::lock_guard<std::mutex> lock(g_mutex);\n    const char *path = env->GetStringUTFChars(jpath, nullptr);\n\n    if (g_ctx)    { llama_free(g_ctx); g_ctx = nullptr; }\n    if (g_model)  { llama_model_free(g_model); g_model = nullptr; }\n\n    llama_backend_init();\n\n    llama_model_params mparams = llama_model_default_params();\n    mparams.n_gpu_layers = 0; // CPU-only by default; raise if you build with GPU support\n    g_model = llama_model_load_from_file(path, mparams);\n    env->ReleaseStringUTFChars(jpath, path);\n    if (!g_model) { LOGE("failed to load model"); return JNI_FALSE; }\n\n    llama_context_params cparams = llama_context_default_params();\n    cparams.n_ctx        = (uint32_t) n_ctx;\n    cparams.n_threads    = (uint32_t) n_threads;\n    cparams.n_threads_batch = (uint32_t) n_threads;\n    cparams.flash_attn_type = LLAMA_FLASH_ATTN_TYPE_ENABLED;\n\n    g_ctx = llama_init_from_model(g_model, cparams);\n    if (!g_ctx) { llama_model_free(g_model); g_model = nullptr; return JNI_FALSE; }\n\n    g_vocab = llama_model_get_vocab(g_model);\n    g_n_ctx = (int32_t) n_ctx;\n    return JNI_TRUE;\n}\n\nJNIEXPORT void JNICALL\nJava_com_personachat_ai_LlmEngine_nativeFree(JNIEnv *, jobject) {\n    std::lock_guard<std::mutex> lock(g_mutex);\n    if (g_ctx)   { llama_free(g_ctx); g_ctx = nullptr; }\n    if (g_model) { llama_model_free(g_model); g_model = nullptr; }\n}\n\nJNIEXPORT void JNICALL\nJava_com_personachat_ai_LlmEngine_nativeStop(JNIEnv *, jobject) {\n    g_stop = true;\n}\n\n// Streaming generation. Runs on the caller\'s thread (use a background thread in Kotlin).\nJNIEXPORT jstring JNICALL\nJava_com_personachat_ai_LlmEngine_nativeGenerate(JNIEnv *env, jobject,\n        jstring jprompt, jfloat temp, jfloat top_p, jint n_predict, jlong seed,\n        jobject jcallback) {\n    std::lock_guard<std::mutex> lock(g_mutex);\n    if (!g_ctx || !g_model) return env->NewStringUTF("");\n\n    g_stop = false;\n    const char *prompt = env->GetStringUTFChars(jprompt, nullptr);\n    std::string prompt_str(prompt);\n    env->ReleaseStringUTFChars(jprompt, prompt);\n\n    // tokenize (with BOS)\n    const int n_max = g_n_ctx - 8;\n    std::vector<llama_token> tokens(n_max + 8);\n    int n_prompt = llama_tokenize(g_vocab, prompt_str.c_str(), (int32_t) prompt_str.size(),\n                                  tokens.data(), tokens.size(), true, true);\n    if (n_prompt < 0) return env->NewStringUTF("");\n    if (n_prompt > n_max) {\n        // keep the tail of the prompt if it doesn\'t fit\n        tokens.erase(tokens.begin(), tokens.begin() + (n_prompt - n_max));\n        n_prompt = n_max;\n    }\n\n    jclass cb_cls = env->GetObjectClass(jcallback);\n    jmethodID cb_mid = env->GetMethodID(cb_cls, "onToken", "(Ljava/lang/String;)V");\n\n    llama_batch batch = llama_batch_get_one(tokens.data(), n_prompt);\n    if (llama_decode(g_ctx, batch) != 0) return env->NewStringUTF("");\n\n    llama_sampler *sp = llama_sampler_chain_init(llama_sampler_chain_default_params());\n    llama_sampler_chain_add(sp, llama_sampler_init_top_p(top_p, 1));\n    llama_sampler_chain_add(sp, llama_sampler_init_temp(temp <= 0.0f ? 0.05f : temp));\n    llama_sampler_chain_add(sp, llama_sampler_init_dist((uint32_t) (seed < 0 ? std::rand() : seed)));\n\n    std::string out;\n    const int n_keep = 256; // rolling window if context fills mid-generation\n    for (int i = 0; i < n_predict && !g_stop; i++) {\n        llama_token tok = llama_sampler_sample(sp, g_ctx, -1);\n        if (llama_vocab_is_eog(g_vocab, tok)) break;\n\n        char buf[256];\n        int n = llama_token_to_piece(g_vocab, tok, buf, sizeof(buf), 0, true);\n        if (n > 0) {\n            std::string piece(buf, n);\n            out += piece;\n            jstring jpiece = env->NewStringUTF(piece.c_str());\n            env->CallVoidMethod(jcallback, cb_mid, jpiece);\n            env->DeleteLocalRef(jpiece);\n        }\n\n        batch = llama_batch_get_one(&tok, 1);\n        if (llama_decode(g_ctx, batch) != 0) break;\n\n        // naive context shift: drop oldest tokens when full\n        if (llama_get_kv_cache_used_cells(g_ctx) >= (uint32_t)(g_n_ctx - 4)) {\n            llama_kv_cache_seq_rm(g_ctx, 0, 1, n_keep);\n            llama_kv_cache_seq_add(g_ctx, 0, n_keep, -1, -1);\n        }\n    }\n\n    llama_sampler_free(sp);\n    return env->NewStringUTF(out.c_str());\n}\n\n// Apply the model\'s built-in chat template (llama_chat_apply_template, tmpl=nullptr).\n// Returns empty string if the model has no template -- caller falls back to a plain format.\nJNIEXPORT jstring JNICALL\nJava_com_personachat_ai_LlmEngine_nativeApplyTemplate(JNIEnv *env, jobject,\n        jobjectArray roles, jobjectArray contents, jboolean add_assistant) {\n    std::lock_guard<std::mutex> lock(g_mutex);\n    if (!g_model) return env->NewStringUTF("");\n\n    jsize n = env->GetArrayLength(roles);\n    std::vector<llama_chat_message> msgs((size_t) n);\n    std::vector<std::string> role_store((size_t) n), content_store((size_t) n);\n    for (jsize i = 0; i < n; i++) {\n        jstring r = (jstring) env->GetObjectArrayElement(roles, i);\n        jstring c = (jstring) env->GetObjectArrayElement(contents, i);\n        const char *rs = env->GetStringUTFChars(r, nullptr);\n        const char *cs = env->GetStringUTFChars(c, nullptr);\n        role_store[i]    = rs;\n        content_store[i] = cs;\n        msgs[i].role    = role_store[i].c_str();\n        msgs[i].content = content_store[i].c_str();\n        env->ReleaseStringUTFChars(r, rs);\n        env->ReleaseStringUTFChars(c, cs);\n        env->DeleteLocalRef(r);\n        env->DeleteLocalRef(c);\n    }\n\n    // fetch the model\'s built-in chat template from metadata\n    char tmpl[8192];\n    int n_tmpl = llama_model_meta_val_str(g_model, "tokenizer.chat_template", tmpl, sizeof(tmpl));\n    const char *tmpl_ptr = (n_tmpl > 0) ? tmpl : nullptr;\n    if (!tmpl_ptr) return env->NewStringUTF(""); // no template -> Kotlin falls back to plain format\n\n    int needed = llama_chat_apply_template(tmpl_ptr, msgs.data(), (size_t) n,\n                                           add_assistant == JNI_TRUE, nullptr, 0);\n    if (needed <= 0) return env->NewStringUTF("");\n    std::vector<char> buf((size_t) needed + 8);\n    llama_chat_apply_template(tmpl_ptr, msgs.data(), (size_t) n,\n                              add_assistant == JNI_TRUE, buf.data(), buf.size());\n    return env->NewStringUTF(buf.data());\n}\n\n} // extern "C"\n', 'app/src/main/java/com/personachat/MainActivity.kt': 'package com.personachat\n\nimport android.os.Bundle\nimport androidx.activity.ComponentActivity\nimport androidx.activity.compose.setContent\nimport androidx.compose.material3.MaterialTheme\nimport androidx.compose.material3.Surface\nimport androidx.navigation.NavType\nimport androidx.navigation.compose.NavHost\nimport androidx.navigation.compose.composable\nimport androidx.navigation.compose.rememberNavController\nimport androidx.navigation.navArgument\nimport com.personachat.data.Repositories\nimport com.personachat.ui.AiModifyScreen\nimport com.personachat.ui.CharacterEditScreen\nimport com.personachat.ui.CharactersScreen\nimport com.personachat.ui.ChatScreen\nimport com.personachat.ui.ModelScreen\n\nclass MainActivity : ComponentActivity() {\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        Repositories.init(this)\n        setContent {\n            MaterialTheme {\n                Surface(color = MaterialTheme.colorScheme.background) {\n                    val nav = rememberNavController()\n                    NavHost(navController = nav, startDestination = "characters") {\n                        composable("characters") {\n                            CharactersScreen(\n                                onOpenModel = { nav.navigate("models") },\n                                onOpenChat = { id -> nav.navigate("chat/$id") },\n                                onCreate = { id -> nav.navigate("edit/$id") }\n                            )\n                        }\n                        composable("models") { ModelScreen(onBack = { nav.popBackStack() }) }\n                        composable(\n                            "edit/{charId}",\n                            arguments = listOf(navArgument("charId") { type = NavType.StringType })\n                        ) { back ->\n                            val id = back.arguments?.getString("charId")!!\n                            CharacterEditScreen(\n                                charId = id,\n                                onBack = { nav.popBackStack() },\n                                onChat = { nav.navigate("chat/$id") },\n                                onAiModify = { nav.navigate("aimodify/$id") }\n                            )\n                        }\n                        composable(\n                            "chat/{charId}",\n                            arguments = listOf(navArgument("charId") { type = NavType.StringType })\n                        ) { back ->\n                            val id = back.arguments?.getString("charId")!!\n                            ChatScreen(charId = id, onBack = { nav.popBackStack() })\n                        }\n                        composable(\n                            "aimodify/{charId}",\n                            arguments = listOf(navArgument("charId") { type = NavType.StringType })\n                        ) { back ->\n                            val id = back.arguments?.getString("charId")!!\n                            AiModifyScreen(charId = id, onBack = { nav.popBackStack() })\n                        }\n                    }\n                }\n            }\n        }\n    }\n}\n', 'app/src/main/java/com/personachat/ai/CharacterModifier.kt': 'package com.personachat.ai\n\nimport com.personachat.data.Character\nimport kotlinx.serialization.json.Json\nimport kotlinx.serialization.json.JsonObject\nimport kotlinx.serialization.json.jsonPrimitive\n\n/**\n * "Modify character with AI": sends the current card + a plain-English instruction\n * to the local model and asks for an updated card inside <<<JSON>>>...<<<END>>>.\n * Parsed and applied locally -- nothing leaves the device.\n */\nobject CharacterModifier {\n\n    private val json = Json { ignoreUnknownKeys = true }\n\n    fun buildPrompt(c: Character, instruction: String): String {\n        val card = buildString {\n            appendLine("name: ${c.name}")\n            appendLine("persona: ${c.persona}")\n            appendLine("scenario: ${c.scenario}")\n            appendLine("greeting: ${c.greeting}")\n            appendLine("exampleDialogue: ${c.exampleDialogue}")\n        }\n        return buildString {\n            appendLine("You edit character cards for a roleplay chat app. Rewrite the card according to the user\'s instruction.")\n            appendLine("Change only what the instruction asks for; keep the rest. Keep every field appropriate and consistent.")\n            appendLine("Output ONLY the updated fields, exactly in this format:")\n            appendLine("<<<JSON>>>")\n            appendLine("{\\"name\\": \\"...\\", \\"persona\\": \\"...\\", \\"scenario\\": \\"...\\", \\"greeting\\": \\"...\\", \\"exampleDialogue\\": \\"...\\"}")\n            appendLine("<<<END>>>")\n            appendLine("No commentary before or after the markers.")\n            appendLine()\n            appendLine("CURRENT CARD:")\n            appendLine(card.trim())\n            appendLine()\n            appendLine("INSTRUCTION: $instruction")\n            appendLine()\n            append("Updated card:")\n        }\n    }\n\n    /** Runs blocking -- call from a background dispatcher. Returns updated copy, or null on parse failure. */\n    fun runBlocking(c: Character, instruction: String, onRaw: (String) -> Unit): Character? {\n        val prompt = buildPrompt(c, instruction)\n        val full = StringBuilder()\n        LlmEngine.generateBlocking(prompt, temp = 0.4f, nPredict = 1400) {\n            full.append(it); onRaw(full.toString())\n        }\n        return parse(c, full.toString())\n    }\n\n    fun parse(c: Character, output: String): Character? {\n        val start = output.indexOf("<<<JSON>>>")\n        val end = output.indexOf("<<<END>>>")\n        val block = if (start >= 0 && end > start) output.substring(start + 10, end) else output\n        return runCatching {\n            val obj = json.parseToJsonElement(block.trim()).jsonObject\n            fun str(k: String, old: String): String =\n                runCatching { obj[k]?.jsonPrimitive?.content?.takeIf { it.isNotBlank() } }\n                    .getOrNull() ?: old\n            c.apply {\n                name = str("name", name)\n                persona = str("persona", persona)\n                scenario = str("scenario", scenario)\n                greeting = str("greeting", greeting)\n                exampleDialogue = str("exampleDialogue", exampleDialogue)\n            }\n        }.getOrNull()\n    }\n}\n', 'app/src/main/java/com/personachat/ai/Downloader.kt': "package com.personachat.ai\n\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.withContext\nimport java.io.File\nimport java.net.HttpURLConnection\nimport java.net.URL\n\nobject Downloader {\n\n    /** Downloads a GGUF straight into the app's private files dir. Resumable=false, simple + cancellable. */\n    suspend fun download(url: String, dest: File, onProgress: (done: Long, total: Long) -> Unit) =\n        withContext(Dispatchers.IO) {\n            dest.parentFile?.mkdirs()\n            val conn = URL(url).openConnection() as HttpURLConnection\n            conn.connectTimeout = 15000\n            conn.readTimeout = 30000\n            conn.connect()\n            val total = conn.contentLengthLong\n            conn.inputStream.use { input ->\n                dest.outputStream().use { output ->\n                    val buf = ByteArray(64 * 1024)\n                    var done = 0L\n                    while (true) {\n                        val r = input.read(buf)\n                        if (r == -1) break\n                        output.write(buf, 0, r)\n                        done += r\n                        onProgress(done, total)\n                    }\n                }\n            }\n        }\n}\n", 'app/src/main/java/com/personachat/ai/HuggingFaceApi.kt': 'package com.personachat.ai\n\nimport org.json.JSONArray\nimport java.net.HttpURLConnection\nimport java.net.URL\nimport java.net.URLEncoder\n\n/**\n * Minimal Hugging Face Hub API client (no API key required).\n * https://huggingface.co/docs/hub/api\n */\nobject HuggingFaceApi {\n\n    data class Repo(val id: String, val downloads: Long, val likes: Int)\n    data class File(val path: String, val size: Long, val url: String)\n\n    private fun get(url: String): String {\n        val conn = URL(url).openConnection() as HttpURLConnection\n        conn.connectTimeout = 15000\n        conn.readTimeout = 20000\n        conn.setRequestProperty("User-Agent", "PersonaChat/1.0")\n        if (conn.responseCode !in 200..299) throw java.io.IOException("HTTP " + conn.responseCode)\n        return conn.inputStream.bufferedReader().use { it.readText() }\n    }\n\n    /** Search GGUF-capable repos on the Hub, most downloaded first. */\n    fun search(query: String, limit: Int = 25): List<Repo> {\n        val q = URLEncoder.encode(query, "UTF-8")\n        val url = "https://huggingface.co/api/models?search=" + q +\n                "&limit=" + limit + "&filter=gguf&sort=downloads&direction=-1"\n        val arr = JSONArray(get(url))\n        return (0 until arr.length()).map { i ->\n            val o = arr.getJSONObject(i)\n            Repo(id = o.optString("id"), downloads = o.optLong("downloads"), likes = o.optInt("likes"))\n        }\n    }\n\n    /** GGUF files in a repo\'s main branch; split shards (00001-of-...) are excluded. */\n    fun ggufFiles(repoId: String): List<File> {\n        val url = "https://huggingface.co/api/models/" + repoId + "/tree/main"\n        val arr = JSONArray(get(url))\n        return (0 until arr.length()).mapNotNull { i ->\n            val o = arr.getJSONObject(i)\n            val path = o.optString("path")\n            if (!path.endsWith(".gguf") || path.contains("-of-")) null\n            else {\n                val encoded = URLEncoder.encode(path, "UTF-8")\n                File(path, o.optLong("size"),\n                    "https://huggingface.co/" + repoId + "/resolve/main/" + encoded)\n            }\n        }\n    }\n}\n', 'app/src/main/java/com/personachat/ai/LlmEngine.kt': 'package com.personachat.ai\n\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.channels.awaitClose\nimport kotlinx.coroutines.flow.Flow\nimport kotlinx.coroutines.flow.callbackFlow\nimport kotlinx.coroutines.flow.flowOn\nimport java.io.File\n\n/**\n * Single-model, single-session engine wrapping llama.cpp through JNI.\n * Everything runs on-device; no network is used for inference.\n */\nobject LlmEngine {\n\n    interface TokenCallback { fun onToken(piece: String) }\n\n    @Volatile\n    var isLoaded: Boolean = false\n        private set\n\n    init { System.loadLibrary("persona-jni") }\n\n    private external fun nativeLoadModel(path: String, nCtx: Int, nThreads: Int): Boolean\n    private external fun nativeFree()\n    private external fun nativeStop()\n    private external fun nativeGenerate(\n        prompt: String, temp: Float, topP: Float, nPredict: Int, seed: Long,\n        callback: TokenCallback\n    ): String\n    private external fun nativeApplyTemplate(\n        roles: Array<String>, contents: Array<String>, addAssistant: Boolean\n    ): String\n\n    fun loadModel(file: File, nCtx: Int = 4096, nThreads: Int = 4): Boolean {\n        val ok = nativeLoadModel(file.absolutePath, nCtx, nThreads)\n        isLoaded = ok\n        return ok\n    }\n\n    fun unload() { nativeFree(); isLoaded = false }\n    fun stop() = nativeStop()\n\n    /** Applies the model\'s built-in chat template; empty string means "no template". */\n    fun applyChatTemplate(messages: List<Pair<String, String>>, addAssistant: Boolean = true): String {\n        if (messages.isEmpty()) return ""\n        return try {\n            nativeApplyTemplate(\n                messages.map { it.first }.toTypedArray(),\n                messages.map { it.second }.toTypedArray(),\n                addAssistant\n            )\n        } catch (t: Throwable) { "" }\n    }\n\n    /** Blocking call -- collect on a background dispatcher. */\n    fun generateBlocking(\n        prompt: String, temp: Float = 0.8f, topP: Float = 0.95f,\n        nPredict: Int = 512, seed: Long = -1, onToken: (String) -> Unit\n    ): String {\n        val cb = object : TokenCallback { override fun onToken(piece: String) = onToken(piece) }\n        return nativeGenerate(prompt, temp, topP, nPredict, seed, cb)\n    }\n\n    fun generateStream(\n        prompt: String, temp: Float = 0.8f, topP: Float = 0.95f,\n        nPredict: Int = 512, seed: Long = -1\n    ): Flow<String> = callbackFlow {\n        val cb = object : TokenCallback {\n            override fun onToken(piece: String) { trySend(piece) }\n        }\n        try {\n            nativeGenerate(prompt, temp, topP, nPredict, seed, cb)\n        } catch (t: Throwable) {\n            trySend("\\n[generation error: ${t.message}]\\n")\n        }\n        close()\n        awaitClose { }\n    }.flowOn(Dispatchers.IO)\n}\n', 'app/src/main/java/com/personachat/ai/PromptBuilder.kt': 'package com.personachat.ai\n\nimport com.personachat.data.Character\nimport com.personachat.data.ChatMessage\n\nobject PromptBuilder {\n\n    fun systemPrompt(c: Character): String = buildString {\n        append("You are ${c.name}, a fictional character in a roleplay chat.\\n")\n        if (c.persona.isNotBlank()) append("Personality and background:\\n${c.persona}\\n")\n        if (c.scenario.isNotBlank()) append("Current scenario/setting:\\n${c.scenario}\\n")\n        if (c.exampleDialogue.isNotBlank()) append("Example dialogue (match this voice):\\n${c.exampleDialogue}\\n")\n        append("\\nRules: Always stay fully in character as ${c.name}. Never break character, ")\n        append("never mention being an AI or a language model, never describe out-of-character actions. ")\n        append("Write as ${c.name} in first person. Keep replies conversational (a few sentences unless the scene calls for more).")\n    }\n\n    /**\n     * Builds the raw prompt. Prefers the model\'s built-in chat template;\n     * falls back to a plain instruct format if the model has none.\n     */\n    fun buildPrompt(c: Character, history: List<ChatMessage>): String {\n        val pairs = buildList {\n            add("system" to systemPrompt(c))\n            history.forEach { add(it.role to it.content) }\n        }\n        val templated = LlmEngine.applyChatTemplate(pairs, addAssistant = true)\n        if (templated.isNotBlank()) return templated\n        // fallback plain format\n        return buildString {\n            append("System: ${systemPrompt(c)}\\n\\n")\n            history.forEach { append("${if (it.role == "user") "User" else c.name}: ${it.content}\\n\\n") }\n            append("${c.name}: ")\n        }\n    }\n\n    /** Trims history so system + recent turns fit roughly in the context budget. */\n    fun trimmedHistory(history: List<ChatMessage>, maxChars: Int = 6000): List<ChatMessage> {\n        val out = ArrayList<ChatMessage>()\n        var used = 0\n        for (m in history.asReversed()) {\n            if (used + m.content.length > maxChars) break\n            out.add(m); used += m.content.length\n        }\n        return out.asReversed()\n    }\n}\n', 'app/src/main/java/com/personachat/data/Models.kt': 'package com.personachat.data\n\nimport kotlinx.serialization.Serializable\n\n@Serializable\ndata class Character(\n    val id: String,\n    var name: String,\n    var avatar: String = "\\uD83E\\uDDD9", // emoji\n    var persona: String = "",          // who the character is\n    var scenario: String = "",         // setting / circumstances\n    var greeting: String = "",         // first message the character sends\n    var exampleDialogue: String = "",\n    val createdAt: Long = System.currentTimeMillis()\n)\n\n@Serializable\ndata class ChatMessage(\n    val role: String, // "system" | "user" | "assistant"\n    val content: String,\n    val ts: Long = System.currentTimeMillis()\n)\n', 'app/src/main/java/com/personachat/data/Repositories.kt': 'package com.personachat.data\n\nimport android.content.Context\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.StateFlow\nimport kotlinx.coroutines.flow.asStateFlow\nimport kotlinx.serialization.encodeToString\nimport kotlinx.serialization.json.Json\nimport java.io.File\nimport java.util.UUID\n\nobject Repositories {\n\n    private val json = Json { ignoreUnknownKeys = true; prettyPrint = true }\n\n    private lateinit var appCtx: Context\n    private val charsFile by lazy { File(appCtx.filesDir, "characters.json") }\n\n    private val _characters = MutableStateFlow<List<Character>>(emptyList())\n    val characters: StateFlow<List<Character>> = _characters.asStateFlow()\n\n    fun init(ctx: Context) {\n        appCtx = ctx.applicationContext\n        _characters.value = loadChars()\n    }\n\n    private inline fun <reified T> load(file: File, default: T): T =\n        runCatching { if (file.exists()) json.decodeFromString<T>(file.readText()) else default }\n            .getOrDefault(default)\n\n    private inline fun <reified T> save(file: File, value: T) {\n        file.writeText(json.encodeToString(value))\n    }\n\n    private fun loadChars(): List<Character> = load(charsFile, emptyList())\n\n    fun newCharacter(): Character {\n        val c = Character(id = UUID.randomUUID().toString(), name = "New Character")\n        upsert(c); return c\n    }\n\n    fun upsert(c: Character) {\n        _characters.value = _characters.value.filterNot { it.id == c.id } + c\n        save(charsFile, _characters.value)\n    }\n\n    fun delete(id: String) {\n        _characters.value = _characters.value.filterNot { it.id == id }\n        save(charsFile, _characters.value)\n        chatFile(id).delete()\n    }\n\n    fun byId(id: String): Character? = _characters.value.find { it.id == id }\n\n    // ---- chat history (one JSON file per character) ----\n\n    private fun chatFile(id: String) = File(appCtx.filesDir, "chat_$id.json")\n\n    fun loadMessages(id: String): List<ChatMessage> = load(chatFile(id), emptyList())\n\n    fun saveMessages(id: String, msgs: List<ChatMessage>) = save(chatFile(id), msgs)\n\n    // ---- local model files ----\n\n    fun ggufDir(): File = appCtx.filesDir\n\n    fun listModels(): List<File> =\n        appCtx.filesDir.listFiles()?.filter { it.extension == "gguf" }?.sortedBy { it.name } ?: emptyList()\n\n    fun newDownloadFile(url: String): File =\n        File(appCtx.filesDir, url.substringAfterLast(\'/\').ifBlank { "model.gguf" })\n}\n', 'app/src/main/java/com/personachat/ui/AiModifyScreen.kt': 'package com.personachat.ui\n\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.rememberScrollState\nimport androidx.compose.foundation.verticalScroll\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.unit.dp\nimport com.personachat.ai.CharacterModifier\nimport com.personachat.ai.LlmEngine\nimport com.personachat.data.Repositories\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.launch\nimport kotlinx.coroutines.withContext\n\n@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun AiModifyScreen(charId: String, onBack: () -> Unit) {\n    val c = remember(charId) { Repositories.byId(charId) } ?: return LaunchedEffect(Unit) { onBack() }\n    val scope = rememberCoroutineScope()\n\n    var instruction by remember { mutableStateOf("") }\n    var raw by remember { mutableStateOf("") }\n    var busy by remember { mutableStateOf(false) }\n    var result by remember { mutableStateOf<String?>(null) }\n    var error by remember { mutableStateOf<String?>(null) }\n\n    Scaffold(topBar = {\n        TopAppBar(title = { Text("AI modify: ${c.name}") },\n            navigationIcon = { TextButton(onBack) { Text("Back") } })\n    }) { pad ->\n        Column(Modifier.padding(pad).padding(16.dp).verticalScroll(rememberScrollState())\n            .fillMaxSize(), verticalArrangement = Arrangement.spacedBy(10.dp)) {\n\n            Text("Describe the change in plain words, e.g. \\"make her a cynical pirate captain\\" or \\"move the scene to a space station\\".",\n                style = MaterialTheme.typography.bodyMedium)\n\n            OutlinedTextField(instruction, { instruction = it },\n                label = { Text("Modification prompt") },\n                modifier = Modifier.fillMaxWidth().heightIn(min = 110.dp), maxLines = 8)\n\n            Button(\n                enabled = !busy && instruction.isNotBlank() && LlmEngine.isLoaded,\n                onClick = {\n                    scope.launch {\n                        busy = true; error = null; result = null; raw = ""\n                        val updated = withContext(Dispatchers.IO) {\n                            runCatching { CharacterModifier.runBlocking(c, instruction) { raw = it } }\n                        }\n                        busy = false\n                        updated.exceptionOrNull()?.let { error = it.message }\n                        val u = updated.getOrNull()\n                        if (u == null && error == null) error = "Could not parse the model output — try again or rephrase."\n                        result = u?.let { "Name: ${it.name}\\n\\nPersona: ${it.persona}\\n\\nScenario: ${it.scenario}\\n\\nGreeting: ${it.greeting}" }\n                        if (u != null) {\n                            // stage into repo only on Apply\n                            pendingUpdate = u\n                        }\n                    }\n                },\n                modifier = Modifier.fillMaxWidth()\n            ) { Text(if (busy) "Thinking..." else "Generate changes") }\n\n            if (!LlmEngine.isLoaded)\n                Text("Load a model first (Models screen).", color = MaterialTheme.colorScheme.error)\n\n            if (raw.isNotBlank()) {\n                Text("Raw output", style = MaterialTheme.typography.labelLarge)\n                Text(raw, style = MaterialTheme.typography.bodySmall)\n            }\n            result?.let {\n                HorizontalDivider()\n                Text("Proposed changes", style = MaterialTheme.typography.titleMedium)\n                Text(it)\n                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                    Button(onClick = {\n                        pendingUpdate?.let { u -> Repositories.upsert(u); pendingUpdate = null; onBack() }\n                    }) { Text("Apply & save") }\n                    OutlinedButton(onClick = { pendingUpdate = null; result = null }) { Text("Discard") }\n                }\n            }\n            error?.let { Text(it, color = MaterialTheme.colorScheme.error) }\n        }\n    }\n}\n\nprivate var pendingUpdate: com.personachat.data.Character? = null\n', 'app/src/main/java/com/personachat/ui/CharacterEditScreen.kt': 'package com.personachat.ui\n\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.rememberScrollState\nimport androidx.compose.foundation.verticalScroll\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.unit.dp\nimport com.personachat.data.Repositories\n\n@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun CharacterEditScreen(charId: String, onBack: () -> Unit, onChat: () -> Unit, onAiModify: () -> Unit) {\n    val c = remember(charId) { Repositories.byId(charId) } ?: return LaunchedEffect(Unit) { onBack() }\n\n    var name by remember { mutableStateOf(c.name) }\n    var avatar by remember { mutableStateOf(c.avatar) }\n    var persona by remember { mutableStateOf(c.persona) }\n    var scenario by remember { mutableStateOf(c.scenario) }\n    var greeting by remember { mutableStateOf(c.greeting) }\n    var example by remember { mutableStateOf(c.exampleDialogue) }\n\n    fun save() {\n        c.name = name; c.avatar = avatar; c.persona = persona\n        c.scenario = scenario; c.greeting = greeting; c.exampleDialogue = example\n        Repositories.upsert(c)\n    }\n\n    Scaffold(topBar = {\n        TopAppBar(title = { Text("Edit character") },\n            navigationIcon = { TextButton(onBack) { Text("Back") } },\n            actions = {\n                TextButton(onClick = { save(); onChat() }) { Text("Save & Chat") }\n                TextButton(onClick = { save() }) { Text("Save") }\n            })\n    }) { pad ->\n        Column(Modifier.padding(pad).padding(16.dp).verticalScroll(rememberScrollState())\n            .fillMaxSize(), verticalArrangement = Arrangement.spacedBy(10.dp)) {\n\n        OutlinedTextField(name, { name = it }, label = { Text("Name") }, modifier = Modifier.fillMaxWidth())\n        OutlinedTextField(avatar, { avatar = it.take(4) }, label = { Text("Avatar emoji") })\n\n        OutlinedTextField(persona, { persona = it },\n            label = { Text("Persona (who they are, speech style, background)") },\n            modifier = Modifier.fillMaxWidth().heightIn(min = 140.dp), maxLines = 12)\n\n        OutlinedTextField(scenario, { scenario = it },\n            label = { Text("Scenario / setting (optional)") },\n            modifier = Modifier.fillMaxWidth().heightIn(min = 90.dp), maxLines = 8)\n\n        OutlinedTextField(greeting, { greeting = it },\n            label = { Text("First message (greeting)") },\n            modifier = Modifier.fillMaxWidth().heightIn(min = 90.dp), maxLines = 8)\n\n        OutlinedTextField(example, { example = it },\n            label = { Text("Example dialogue (optional)") },\n            modifier = Modifier.fillMaxWidth().heightIn(min = 90.dp), maxLines = 8)\n\n        Button(onClick = { save(); onAiModify() }, modifier = Modifier.fillMaxWidth()) {\n            Text("\\u2728 Modify with AI (prompt)")\n        }\n\n        OutlinedButton(onClick = { Repositories.delete(charId); onBack() },\n            modifier = Modifier.fillMaxWidth()) { Text("Delete character") }\n        }\n    }\n}\n', 'app/src/main/java/com/personachat/ui/CharactersScreen.kt': 'package com.personachat.ui\n\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.lazy.LazyColumn\nimport androidx.compose.foundation.lazy.items\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.unit.dp\nimport androidx.lifecycle.compose.collectAsStateWithLifecycle\nimport com.personachat.ai.LlmEngine\nimport com.personachat.data.Repositories\n\n@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun CharactersScreen(onOpenModel: () -> Unit, onOpenChat: (String) -> Unit, onCreate: (String) -> Unit) {\n    val chars by Repositories.characters.collectAsStateWithLifecycle()\n\n    Scaffold(\n        topBar = {\n            TopAppBar(title = { Text("PersonaChat") }, actions = {\n                TextButton(onOpenModel) {\n                    Text(if (LlmEngine.isLoaded) "Model \\u2713" else "Load model")\n                }\n            })\n        },\n        floatingActionButton = {\n            ExtendedFloatingActionButton(\n                text = { Text("New character") },\n                icon = { Text("+") },\n                onClick = { onCreate(Repositories.newCharacter().id) }\n            )\n        }\n    ) { pad ->\n        LazyColumn(Modifier.padding(pad).padding(16.dp).fillMaxSize(),\n            verticalArrangement = Arrangement.spacedBy(10.dp)) {\n            items(chars, key = { it.id }) { c ->\n                ElevatedCard(Modifier.fillMaxWidth(), onClick = { onOpenChat(c.id) }) {\n                    Row(Modifier.padding(14.dp), horizontalArrangement = Arrangement.spacedBy(12.dp)) {\n                        Text(c.avatar, style = MaterialTheme.typography.headlineMedium)\n                        Column {\n                            Text(c.name, style = MaterialTheme.typography.titleMedium)\n                            Text(c.persona.take(90), style = MaterialTheme.typography.bodySmall,\n                                maxLines = 2)\n                        }\n                    }\n                }\n            }\n        }\n    }\n}\n', 'app/src/main/java/com/personachat/ui/ChatScreen.kt': 'package com.personachat.ui\n\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.lazy.LazyColumn\nimport androidx.compose.foundation.lazy.itemsIndexed\nimport androidx.compose.foundation.lazy.rememberLazyListState\nimport androidx.compose.foundation.shape.RoundedCornerShape\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.unit.dp\nimport androidx.lifecycle.compose.collectAsStateWithLifecycle\nimport androidx.lifecycle.viewmodel.compose.viewModel\nimport com.personachat.ai.LlmEngine\nimport com.personachat.vm.ChatViewModel\n\n@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun ChatScreen(charId: String, onBack: () -> Unit) {\n    val vm: ChatViewModel = viewModel()\n    val messages by vm.messages.collectAsStateWithLifecycle()\n    val streaming by vm.streaming.collectAsStateWithLifecycle()\n    val generating by vm.generating.collectAsStateWithLifecycle()\n    var input by remember { mutableStateOf("") }\n    val listState = rememberLazyListState()\n    val name = vm.character?.name ?: "Chat"\n\n    LaunchedEffect(messages.size, streaming?.length) {\n        val last = listState.layoutInfo.totalItemsCount\n        if (last > 0) listState.animateScrollToItem(last - 1)\n    }\n\n    Scaffold(topBar = {\n        TopAppBar(\n            title = { Text(name) },\n            navigationIcon = { TextButton(onBack) { Text("Back") } },\n            actions = {\n                if (generating) TextButton(onClick = { vm.stop() }) { Text("Stop") }\n                TextButton(onClick = { vm.clearChat() }) { Text("Clear") }\n            }\n        )\n    }) { pad ->\n        Column(Modifier.padding(pad).fillMaxSize()) {\n            if (!LlmEngine.isLoaded) {\n                Text("No model loaded — go to \'Load model\' first.",\n                    modifier = Modifier.padding(16.dp),\n                    color = MaterialTheme.colorScheme.error)\n            }\n            LazyColumn(\n                state = listState,\n                modifier = Modifier.weight(1f).padding(horizontal = 12.dp),\n                verticalArrangement = Arrangement.spacedBy(8.dp),\n                contentPadding = PaddingValues(vertical = 12.dp)\n            ) {\n                itemsIndexed(messages, key = { i, m -> m.ts.toString() + m.role + i }) { _, m ->\n                    Bubble(m.role == "user", m.content)\n                }\n                if (streaming != null) item { Bubble(false, streaming!!, streaming = true) }\n            }\n            Row(Modifier.padding(12.dp).fillMaxWidth(),\n                horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                OutlinedTextField(\n                    value = input, onValueChange = { input = it },\n                    modifier = Modifier.weight(1f),\n                    placeholder = { Text("Message $name...") },\n                    maxLines = 4\n                )\n                Button(\n                    enabled = !generating && LlmEngine.isLoaded && input.isNotBlank(),\n                    onClick = { vm.send(input); input = "" }\n                ) { Text("Send") }\n            }\n        }\n    }\n}\n\n@Composable\nprivate fun Bubble(isUser: Boolean, text: String, streaming: Boolean = false) {\n    Row(Modifier.fillMaxWidth(), horizontalArrangement =\n        if (isUser) Arrangement.End else Arrangement.Start) {\n        Surface(\n            color = if (isUser) MaterialTheme.colorScheme.primaryContainer\n            else MaterialTheme.colorScheme.secondaryContainer,\n            shape = RoundedCornerShape(16.dp),\n            modifier = Modifier.widthIn(max = 320.dp)\n        ) {\n            Text(\n                text + if (streaming) " ▍" else "",\n                modifier = Modifier.padding(12.dp),\n                style = MaterialTheme.typography.bodyLarge\n            )\n        }\n    }\n}\n', 'app/src/main/java/com/personachat/ui/ModelScreen.kt': 'package com.personachat.ui\n\nimport androidx.compose.foundation.clickable\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.lazy.LazyColumn\nimport androidx.compose.foundation.lazy.items\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.unit.dp\nimport com.personachat.ai.Downloader\nimport com.personachat.ai.HuggingFaceApi\nimport com.personachat.ai.LlmEngine\nimport com.personachat.data.Repositories\nimport kotlinx.coroutines.launch\n\n@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun ModelScreen(onBack: () -> Unit) {\n    val scope = rememberCoroutineScope()\n    var models by remember { mutableStateOf(Repositories.listModels()) }\n    var status by remember { mutableStateOf("") }\n    var url by remember { mutableStateOf("") }\n    var progress by remember { mutableStateOf<Float?>(null) }\n    var ctxSize by remember { mutableStateOf(4096f) }\n\n    // ---- Hugging Face browser state ----\n    var query by remember { mutableStateOf("") }\n    var repos by remember { mutableStateOf<List<HuggingFaceApi.Repo>>(emptyList()) }\n    var files by remember { mutableStateOf<List<HuggingFaceApi.File>>(emptyList()) }\n    var selectedRepo by remember { mutableStateOf<String?>(null) }\n    var searching by remember { mutableStateOf(false) }\n\n    fun refresh() { models = Repositories.listModels() }\n\n    Scaffold(topBar = {\n        TopAppBar(title = { Text("Local model") },\n            navigationIcon = { TextButton(onBack) { Text("Back") } })\n    }) { pad ->\n        LazyColumn(\n            modifier = Modifier.padding(pad).padding(horizontal = 16.dp).fillMaxSize(),\n            verticalArrangement = Arrangement.spacedBy(10.dp),\n            contentPadding = PaddingValues(vertical = 12.dp)\n        ) {\n            item {\n                OutlinedTextField(url, { url = it }, label = { Text("GGUF download URL") },\n                    modifier = Modifier.fillMaxWidth(), singleLine = true)\n                Row(horizontalArrangement = Arrangement.spacedBy(8.dp),\n                    verticalAlignment = Alignment.CenterVertically) {\n                    Button(enabled = progress == null && url.isNotBlank(), onClick = {\n                        scope.launch {\n                            try {\n                                status = "Downloading..."\n                                val dest = Repositories.newDownloadFile(url)\n                                Downloader.download(url, dest) { done, total ->\n                                    progress = if (total > 0) done.toFloat() / total else null\n                                    status = "Downloading %.1f MB".format(done / 1e6)\n                                }\n                                status = "Saved: ${dest.name}"\n                                refresh()\n                            } catch (t: Throwable) { status = "Download failed: ${t.message}" }\n                            progress = null\n                        }\n                    }) { Text("Download") }\n                    if (progress != null) progress?.let { CircularProgressIndicator(progress = it) }\n                }\n            }\n\n            // ---- Hugging Face model browser ----\n            item {\n                HorizontalDivider()\n                Text("Browse Hugging Face (GGUF)", style = MaterialTheme.typography.titleMedium)\n                Row(horizontalArrangement = Arrangement.spacedBy(8.dp),\n                    verticalAlignment = Alignment.CenterVertically) {\n                    OutlinedTextField(query, { query = it; selectedRepo = null; files = emptyList() },\n                        label = { Text("Search models, e.g. qwen3, llama-3.2") },\n                        modifier = Modifier.weight(1f), singleLine = true)\n                    Button(enabled = !searching && query.isNotBlank(), onClick = {\n                        scope.launch {\n                            searching = true; status = "Searching..."\n                            try { repos = HuggingFaceApi.search(query) }\n                            catch (t: Throwable) { repos = emptyList(); status = "Search failed: ${t.message}" }\n                            searching = false\n                            if (status.startsWith("Searching")) status = "${repos.size} results"\n                        }\n                    }) { Text(if (searching) "..." else "Search") }\n                }\n            }\n\n            items(repos, key = { it.id }) { r ->\n                ElevatedCard(Modifier.fillMaxWidth().clickable {\n                    selectedRepo = r.id\n                    scope.launch {\n                        status = "Listing files for ${r.id}..."\n                        try { files = HuggingFaceApi.ggufFiles(r.id) }\n                        catch (t: Throwable) { files = emptyList(); status = "Failed: ${t.message}" }\n                        if (files.isEmpty()) status = "${r.id}: no loadable .gguf files found"\n                    }\n                }) {\n                    Row(Modifier.padding(12.dp).fillMaxWidth(),\n                        horizontalArrangement = Arrangement.SpaceBetween) {\n                        Text(r.id.substringAfter(\'/\'), style = MaterialTheme.typography.titleMedium,\n                            modifier = Modifier.weight(1f))\n                        Text("${"%,d".format(r.downloads)} dl · ${r.likes} likes",\n                            style = MaterialTheme.typography.bodySmall)\n                    }\n                    if (selectedRepo == r.id) {\n                        files.forEach { f ->\n                            Row(Modifier.padding(horizontal = 12.dp, vertical = 6.dp)\n                                .fillMaxWidth(),\n                                horizontalArrangement = Arrangement.SpaceBetween,\n                                verticalAlignment = Alignment.CenterVertically) {\n                                Column(Modifier.weight(1f)) {\n                                    Text(f.path.substringAfterLast(\'/\'),\n                                        style = MaterialTheme.typography.bodyMedium)\n                                    Text("%.2f GB".format(f.size / 1e9),\n                                        style = MaterialTheme.typography.bodySmall)\n                                }\n                                Button(onClick = {\n                                    scope.launch {\n                                        try {\n                                            status = "Downloading ${f.path.substringAfterLast(\'/\')}..."\n                                            val dest = Repositories.newDownloadFile(f.url)\n                                            Downloader.download(f.url, dest) { done, total ->\n                                                progress = if (total > 0) done.toFloat() / total else null\n                                                status = "Downloading %.1f MB".format(done / 1e6)\n                                            }\n                                            status = "Saved: ${dest.name}"; refresh()\n                                        } catch (t: Throwable) { status = "Download failed: ${t.message}" }\n                                        progress = null\n                                    }\n                                }, enabled = progress == null) { Text("Get") }\n                            }\n                        }\n                    }\n                }\n            }\n\n            item {\n                HorizontalDivider()\n                Text("Context size: ${ctxSize.toInt()} tokens", style = MaterialTheme.typography.labelLarge)\n                Slider(ctxSize, { ctxSize = it }, valueRange = 2048f..16384f, steps = 6)\n                Text(status, style = MaterialTheme.typography.bodyMedium)\n                if (LlmEngine.isLoaded)\n                    Text("Model loaded ✓", color = MaterialTheme.colorScheme.primary)\n            }\n\n            items(models, key = { it.name }) { f ->\n                ElevatedCard(Modifier.fillMaxWidth()) {\n                    Row(Modifier.padding(12.dp).fillMaxWidth(),\n                        horizontalArrangement = Arrangement.SpaceBetween) {\n                        Column(Modifier.weight(1f)) {\n                            Text(f.name, style = MaterialTheme.typography.titleMedium)\n                            Text("%.1f MB".format(f.length() / 1e6),\n                                style = MaterialTheme.typography.bodySmall)\n                        }\n                        if (LlmEngine.isLoaded) {\n                            OutlinedButton(onClick = { LlmEngine.unload(); status = "Unloaded" }) {\n                                Text("Unload")\n                            }\n                        } else {\n                            Button(onClick = {\n                                scope.launch {\n                                    status = "Loading ${f.name}..."\n                                    status = if (LlmEngine.loadModel(f, ctxSize.toInt()))\n                                        "Loaded ${f.name}" else "Failed to load model"\n                                }\n                            }) { Text("Load") }\n                        }\n                    }\n                }\n            }\n\n            item { OutlinedButton(onClick = refresh, modifier = Modifier.fillMaxWidth()) { Text("Rescan files") } }\n        }\n    }\n}\n', 'app/src/main/java/com/personachat/vm/ChatViewModel.kt': 'package com.personachat.vm\n\nimport androidx.lifecycle.SavedStateHandle\nimport androidx.lifecycle.ViewModel\nimport androidx.lifecycle.viewModelScope\nimport com.personachat.ai.LlmEngine\nimport com.personachat.ai.PromptBuilder\nimport com.personachat.data.ChatMessage\nimport com.personachat.data.Repositories\nimport kotlinx.coroutines.Job\nimport kotlinx.coroutines.flow.MutableStateFlow\nimport kotlinx.coroutines.flow.StateFlow\nimport kotlinx.coroutines.flow.asStateFlow\nimport kotlinx.coroutines.launch\n\nclass ChatViewModel(saved: SavedStateHandle) : ViewModel() {\n\n    val charId: String = checkNotNull(saved["charId"])\n    val character = Repositories.byId(charId)\n\n    private val _messages = MutableStateFlow<List<ChatMessage>>(emptyList())\n    val messages: StateFlow<List<ChatMessage>> = _messages.asStateFlow()\n\n    private val _streaming = MutableStateFlow<String?>(null)\n    val streaming: StateFlow<String?> = _streaming.asStateFlow()\n\n    private val _generating = MutableStateFlow(false)\n    val generating: StateFlow<Boolean> = _generating.asStateFlow()\n\n    var temperature = 0.8f\n\n    private var job: Job? = null\n\n    init {\n        _messages.value = Repositories.loadMessages(charId)\n        if (_messages.value.isEmpty() && !character?.greeting.isNullOrBlank()) {\n            val greet = ChatMessage("assistant", character!!.greeting)\n            _messages.value = listOf(greet)\n            persist()\n        }\n    }\n\n    fun send(userText: String) {\n        if (job?.isActive == true || userText.isBlank() || character == null) return\n        if (!LlmEngine.isLoaded) return\n\n        val history = _messages.value + ChatMessage("user", userText)\n        _messages.value = history\n        persist()\n\n        val prompt = PromptBuilder.buildPrompt(character, PromptBuilder.trimmedHistory(history))\n        _generating.value = true\n        val acc = StringBuilder()\n\n        job = viewModelScope.launch {\n            LlmEngine.generateStream(prompt, temp = temperature, nPredict = 600).collect { piece ->\n                acc.append(piece)\n                _streaming.value = acc.toString()\n            }\n            val reply = acc.toString().trim()\n            _streaming.value = null\n            _generating.value = false\n            if (reply.isNotEmpty()) {\n                _messages.value = _messages.value + ChatMessage("assistant", reply)\n                persist()\n            }\n        }\n    }\n\n    fun stop() { LlmEngine.stop() }\n\n    fun clearChat() {\n        stop(); job?.cancel()\n        _messages.value = emptyList()\n        _streaming.value = null\n        _generating.value = false\n        persist()\n    }\n\n    private fun persist() = Repositories.saveMessages(charId, _messages.value)\n}\n', 'gradle/wrapper/gradle-wrapper.properties': 'distributionBase=GRADLE_USER_HOME\ndistributionPath=wrapper/dists\ndistributionUrl=https\\://services.gradle.org/distributions/gradle-8.7-bin.zip\nzipStoreBase=GRADLE_USER_HOME\nzipStorePath=wrapper/dists\n'}

IOS_FILES = {'README.md': '# PersonaChat iOS — offline character chat (llama.cpp)\n\nSwiftUI twin of the Android app: create characters, chat with streaming replies,\nrewrite character cards with a plain-English prompt — all on-device. No accounts,\nno server, no filtering layer added by the app; behavior is whatever GGUF model\nyou load.\n\n## Build\n1. macOS + Xcode 15+, then install XcodeGen: `brew install xcodegen`\n2. `./scripts/fetch_llama_cpp.sh`   (clones llama.cpp into Packages/, it ships Package.swift)\n3. `xcodegen generate`              (creates PersonaChat.xcodeproj from project.yml)\n4. `open PersonaChat.xcodeproj`, pick your team/signing, run on a real device\n   (ARM64 simulator works for UI; inference is slow but functional).\n\n## Getting a GGUF\nSame rules as Android: single-file .gguf, 1-4B params, Q4_K_M default.\nFiles live in the app\'s Documents directory (Models tab shows them).\n\n**Easiest path:** the Models tab has a **Browse Hugging Face (GGUF)** search box — it\nqueries the public Hugging Face Hub API (no key needed), sorts by downloads, and tapping\na repo lists its loadable `.gguf` files (split shards filtered out) with sizes; tap **Get**\nto download. A manual "download by URL" field is there as a fallback, and you can also drop\na file into the app\'s Documents via the Files app / Xcode Devices window.\n\nExample (~1.3GB): https://huggingface.co/bartowski/Qwen_Qwen3-1.7B-GGUF/resolve/main/Qwen3-1.7B-Q4_K_M.gguf\n\nDownloaded models are excluded from iCloud backup.\n\n## Notes\n- CPU-only by default (`n_gpu_layers = 0` in LLMEngine.swift). Metal offload requires\n  building llama.cpp with Metal enabled in its Package.swift.\n- llama.cpp renames C API symbols occasionally; if the build breaks on one, fix it in\n  LLMEngine.swift only.\n- If XcodeGen fails on the SPM product, open Packages/llama.cpp/Package.swift and use\n  the exact library product name listed there in project.yml.\n', 'project.yml': 'name: PersonaChat\noptions:\n  bundleIdPrefix: com.personachat\n  createIntermediateGroups: true\npackages:\n  LlamaCpp:\n    path: Packages/llama.cpp   # run scripts/fetch_llama_cpp.sh first\ntargets:\n  PersonaChat:\n    type: application\n    platform: iOS\n    deploymentTarget: "16.0"\n    sources:\n      - path: PersonaChat\n    dependencies:\n      - package: LlamaCpp\n        product: llama        # if resolution fails, check products in Packages/llama.cpp/Package.swift\n    info:\n      path: PersonaChat/Info.plist\n      properties:\n        CFBundleDisplayName: PersonaChat\n        UILaunchScreen: {}\n        UISupportedInterfaceOrientations:\n          - UIInterfaceOrientationPortrait\n        UIApplicationSceneManifest:\n          UIApplicationSupportsMultipleScenes: false\n    settings:\n      base:\n        SWIFT_VERSION: "5.0"\n        CODE_SIGN_STYLE: Automatic\n        TARGETED_DEVICE_FAMILY: "1,2"\n        ENABLE_USER_SCRIPT_SANDBOXING: NO\n', 'PersonaChat/AiModifyView.swift': 'import SwiftUI\n\nstruct AiModifyView: View {\n    let character: Character\n    var onApply: (Character) -> Void\n    @Environment(\\.dismiss) private var dismiss\n\n    @State private var instruction = ""\n    @State private var raw = ""\n    @State private var proposed: Character?\n    @State private var busy = false\n    @State private var error: String?\n\n    var body: some View {\n        Form {\n            Section {\n                Text("Describe the change in plain words, e.g. \\"make her a cynical pirate captain\\".")\n                    .font(.caption).foregroundStyle(.secondary)\n                TextEditor(text: $instruction).frame(minHeight: 90)\n                Button(busy ? "Thinking..." : "Generate changes") { run() }\n                    .disabled(busy || instruction.isEmpty || !LLMEngine.shared.isLoaded)\n                if !LLMEngine.shared.isLoaded {\n                    Text("Load a model first (Model tab).").foregroundStyle(.red)\n                }\n            }\n            if !raw.isEmpty {\n                Section("Raw output") {\n                    Text(raw).font(.caption2).textSelection(.enabled)\n                }\n            }\n            if let p = proposed {\n                Section("Proposed changes") {\n                    Text("Name: \\(p.name)\\n\\nPersona: \\(p.persona)\\n\\nScenario: \\(p.scenario)\\n\\nGreeting: \\(p.greeting)")\n                    Button("Apply & save") {\n                        onApply(p); dismiss()\n                    }\n                    Button("Discard", role: .destructive) { proposed = nil }\n                }\n            }\n            if let error {\n                Text(error).foregroundStyle(.red)\n            }\n        }\n        .navigationTitle("AI modify")\n    }\n\n    private func run() {\n        busy = true; error = nil; proposed = nil; raw = ""\n        let c = character\n        Task.detached(priority: .userInitiated) {\n            let result = CharacterModifier.run(c: c, instruction: instruction) { snapshot in\n                Task { @MainActor in raw = snapshot }\n            }\n            await MainActor.run {\n                busy = false\n                if let result { proposed = result }\n                else { error = "Could not parse the model output — try again or rephrase." }\n            }\n        }\n    }\n}\n', 'PersonaChat/CharacterEditView.swift': 'import SwiftUI\n\nstruct CharacterEditView: View {\n    @State var character: Character\n    @Environment(\\.dismiss) private var dismiss\n    @State private var showAiModify = false\n\n    var body: some View {\n        Form {\n            Section("Basics") {\n                TextField("Name", text: $character.name)\n                TextField("Avatar emoji", text: $character.avatar)\n            }\n            Section("Persona (who they are, speech style, background)") {\n                TextEditor(text: $character.persona).frame(minHeight: 120)\n            }\n            Section("Scenario / setting (optional)") {\n                TextEditor(text: $character.scenario).frame(minHeight: 70)\n            }\n            Section("First message (greeting)") {\n                TextEditor(text: $character.greeting).frame(minHeight: 70)\n            }\n            Section("Example dialogue (optional)") {\n                TextEditor(text: $character.exampleDialogue).frame(minHeight: 70)\n            }\n            Section {\n                Button("\\u{2728} Modify with AI (prompt)") { showAiModify = true }\n                Button("Delete character", role: .destructive) {\n                    CharacterStore.shared.delete(character.id)\n                    dismiss()\n                }\n            }\n        }\n        .navigationTitle("Edit \\(character.name)")\n        .toolbar {\n            ToolbarItem(placement: .confirmationAction) {\n                Button("Save") { CharacterStore.shared.upsert(character); dismiss() }\n            }\n        }\n        .background(\n            NavigationLink(destination: AiModifyView(character: character, onApply: { updated in\n                character = updated\n                CharacterStore.shared.upsert(updated)\n            }), isActive: $showAiModify) { EmptyView() }.hidden()\n        )\n    }\n}\n', 'PersonaChat/CharacterModifier.swift': 'import Foundation\n\n/// AI card rewrite: meta-prompt -> local model -> <<<JSON>>>...<<<END>>> -> parse.\nenum CharacterModifier {\n    static func buildPrompt(c: Character, instruction: String) -> String {\n        var s = "You edit character cards for a roleplay chat app. Rewrite the card according to the user\'s instruction.\\n"\n        s += "Change only what the instruction asks for; keep the rest. Keep every field appropriate and consistent.\\n"\n        s += "Output ONLY the updated fields, exactly in this format:\\n"\n        s += "<<<JSON>>>\\n"\n        s += "{\\"name\\": \\"...\\", \\"persona\\": \\"...\\", \\"scenario\\": \\"...\\", \\"greeting\\": \\"...\\", \\"exampleDialogue\\": \\"...\\"}\\n"\n        s += "<<<END>>>\\n"\n        s += "No commentary before or after the markers.\\n\\n"\n        s += "CURRENT CARD:\\n"\n        s += "name: \\(c.name)\\n"\n        s += "persona: \\(c.persona)\\n"\n        s += "scenario: \\(c.scenario)\\n"\n        s += "greeting: \\(c.greeting)\\n"\n        s += "exampleDialogue: \\(c.exampleDialogue)\\n\\n"\n        s += "INSTRUCTION: \\(instruction)\\n\\n"\n        s += "Updated card:"\n        return s\n    }\n\n    /// Blocking — call from a background thread. Returns updated copy or nil on parse failure.\n    static func run(c: Character, instruction: String, onRaw: @escaping (String) -> Void) -> Character? {\n        var full = ""\n        LLMEngine.shared.generate(prompt: buildPrompt(c: c, instruction: instruction),\n                                  temp: 0.4, nPredict: 1400) { piece in\n            full += piece\n            onRaw(full)\n        }\n        return parse(c: c, output: full)\n    }\n\n    static func parse(c: Character, output: String) -> Character? {\n        var block = output\n        if let s = block.range(of: "<<<JSON>>>"), let e = block.range(of: "<<<END>>>"), s.upperBound < e.lowerBound {\n            block = String(block[s.upperBound..<e.lowerBound])\n        }\n        guard let data = block.trimmingCharacters(in: .whitespacesAndNewlines).data(using: .utf8),\n              let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }\n        func str(_ k: String, _ old: String) -> String {\n            (obj[k] as? String).flatMap { $0.isEmpty ? nil : $0 } ?? old\n        }\n        var copy = c\n        copy.name = str("name", c.name)\n        copy.persona = str("persona", c.persona)\n        copy.scenario = str("scenario", c.scenario)\n        copy.greeting = str("greeting", c.greeting)\n        copy.exampleDialogue = str("exampleDialogue", c.exampleDialogue)\n        return copy\n    }\n}\n', 'PersonaChat/CharactersView.swift': 'import SwiftUI\n\nstruct CharactersView: View {\n    @ObservedObject var store = CharacterStore.shared\n    @State private var showNew = false\n    @State private var newId: UUID?\n\n    var body: some View {\n        List {\n            ForEach(store.characters) { c in\n                NavigationLink(value: c.id) {\n                    HStack(spacing: 12) {\n                        Text(c.avatar).font(.largeTitle)\n                        VStack(alignment: .leading) {\n                            Text(c.name).font(.headline)\n                            Text(String(c.persona.prefix(90))).font(.caption).lineLimit(2)\n                                .foregroundStyle(.secondary)\n                        }\n                    }\n                }\n            }\n            .onDelete { idx in\n                if let first = idx.first { store.delete(store.characters[first].id) }\n            }\n        }\n        .navigationTitle("PersonaChat")\n        .navigationDestination(for: UUID.self) { id in\n            if let c = store.characters.first(where: { $0.id == id }) {\n                ChatView(character: c)\n            }\n        }\n        .background(\n            NavigationLink(destination: editDestination, isActive: $showNew) { EmptyView() }\n                .hidden()\n        )\n        .toolbar {\n            ToolbarItem(placement: .primaryAction) {\n                Button {\n                    newId = store.newCharacter().id\n                    showNew = true\n                } label: { Image(systemName: "plus") }\n            }\n        }\n    }\n\n    @ViewBuilder private var editDestination: some View {\n        if let id = newId, let c = store.characters.first(where: { $0.id == id }) {\n            CharacterEditView(character: c)\n        } else {\n            Text("…")\n        }\n    }\n}\n', 'PersonaChat/ChatView.swift': 'import SwiftUI\n\nstruct ChatView: View {\n    @StateObject private var vm: ChatViewModel\n    @State private var input = ""\n    @Environment(\\.dismiss) private var dismiss\n\n    init(character: Character) {\n        _vm = StateObject(wrappedValue: ChatViewModel(character: character))\n    }\n\n    var body: some View {\n        VStack {\n            if !LLMEngine.shared.isLoaded {\n                Text("No model loaded — open the Model tab first.")\n                    .foregroundStyle(.red).padding()\n            }\n            ScrollViewReader { proxy in\n                ScrollView {\n                    LazyVStack(spacing: 8) {\n                        ForEach(vm.messages) { m in\n                            Bubble(isUser: m.role == "user", text: m.content)\n                                .id(m.id)\n                        }\n                        if !vm.streaming.isEmpty {\n                            Bubble(isUser: false, text: vm.streaming + " ▍")\n                                .id("streaming")\n                        }\n                    }\n                    .padding(.horizontal, 12)\n                }\n                .onChange(of: vm.messages.count) { _ in scroll(proxy) }\n                .onChange(of: vm.streaming) { _ in scroll(proxy) }\n            }\n            HStack {\n                TextField("Message \\(vm.character.name)...", text: $input, axis: .vertical)\n                    .textFieldStyle(.roundedBorder).lineLimit(1...4)\n                Button("Send") {\n                    vm.send(input); input = ""\n                }\n                .disabled(vm.generating || input.isEmpty || !LLMEngine.shared.isLoaded)\n            }\n            .padding(12)\n        }\n        .navigationTitle(vm.character.name)\n        .toolbar {\n            ToolbarItem(placement: .primaryAction) {\n                Button("Clear") { vm.clearChat() }\n            }\n            if vm.generating {\n                ToolbarItem(placement: .cancellationAction) {\n                    Button("Stop") { vm.stop() }\n                }\n            }\n        }\n    }\n\n    private func scroll(_ proxy: ScrollViewProxy) {\n        withAnimation {\n            if let last = vm.messages.last { proxy.scrollTo(last.id, anchor: .bottom) }\n            else { proxy.scrollTo("streaming", anchor: .bottom) }\n        }\n    }\n}\n\nstruct Bubble: View {\n    let isUser: Bool\n    let text: String\n    var body: some View {\n        HStack {\n            if isUser { Spacer(minLength: 60) }\n            Text(text)\n                .padding(12)\n                .background(isUser ? Color.accentColor.opacity(0.2) : Color(.secondarySystemBackground))\n                .clipShape(RoundedRectangle(cornerRadius: 16))\n            if !isUser { Spacer(minLength: 60) }\n        }\n    }\n}\n', 'PersonaChat/ChatViewModel.swift': 'import Foundation\nimport Combine\n\n@MainActor\nfinal class ChatViewModel: ObservableObject {\n    let character: Character\n    @Published var messages: [ChatMessage] = []\n    @Published var streaming: String = ""\n    @Published var generating = false\n    var temperature: Float = 0.8\n\n    private let store = CharacterStore.shared\n    private var genTask: Task<Void, Never>?\n\n    init(character: Character) {\n        self.character = character\n        messages = store.loadMessages(character.id)\n        if messages.isEmpty, !character.greeting.isEmpty {\n            messages = [ChatMessage(role: "assistant", content: character.greeting)]\n            persist()\n        }\n    }\n\n    func send(_ text: String) {\n        guard !generating, !text.isEmpty, LLMEngine.shared.isLoaded else { return }\n        messages.append(ChatMessage(role: "user", content: text))\n        persist()\n        let prompt = PromptBuilder.buildPrompt(c: character,\n                                               history: PromptBuilder.trimmed(messages))\n        generating = true\n        streaming = ""\n        genTask = Task.detached(priority: .userInitiated) { [weak self] in\n            var acc = ""\n            LLMEngine.shared.generate(prompt: prompt, temp: 0.8, nPredict: 600) { piece in\n                acc += piece\n                let snapshot = acc\n                Task { @MainActor in self?.streaming = snapshot }\n            }\n            let reply = acc.trimmingCharacters(in: .whitespacesAndNewlines)\n            Task { @MainActor in\n                guard let self else { return }\n                self.streaming = ""\n                self.generating = false\n                if !reply.isEmpty {\n                    self.messages.append(ChatMessage(role: "assistant", content: reply))\n                    self.persist()\n                }\n            }\n        }\n    }\n\n    func stop() { LLMEngine.shared.stop() }\n\n    func clearChat() {\n        stop(); genTask?.cancel()\n        messages = []; streaming = ""; generating = false\n        persist()\n    }\n\n    private func persist() { store.saveMessages(character.id, messages) }\n}\n', 'PersonaChat/DownloadManager.swift': 'import Foundation\n\nenum DownloadManager {\n    /// Streams a remote file to disk with progress. Follows redirects (HF resolve URLs).\n    static func download(url: URL, dest: URL, onProgress: @escaping @Sendable (Int64, Int64?) -> Void) async throws {\n        let (bytes, response) = try await URLSession.shared.bytes(for: URLRequest(url: url))\n        let total = (response as? HTTPURLResponse)?.expectedContentLength\n        ModelFiles.excludeFromBackup(dest)\n        FileManager.default.createFile(atPath: dest.path, contents: nil)\n        let handle = try FileHandle(forWritingTo: dest)\n        defer { try? handle.close() }\n        var done: Int64 = 0\n        for try await byte in bytes {\n            try handle.write(contentsOf: Data([byte]))\n            done += 1\n            onProgress(done, total)\n        }\n    }\n}\n', 'PersonaChat/HFApi.swift': 'import Foundation\n\n/// Minimal Hugging Face Hub API client (no API key required).\n/// https://huggingface.co/docs/hub/api\nenum HFApi {\n    struct Repo: Identifiable, Decodable {\n        let id: String\n        let downloads: Int?\n        let likes: Int?\n        var displayName: String { id.components(separatedBy: "/").last ?? id }\n    }\n    private struct TreeNode: Decodable { let path: String; let size: Int64? }\n\n    static func search(_ query: String, limit: Int = 25) async throws -> [Repo] {\n        var comp = URLComponents(string: "https://huggingface.co/api/models")!\n        comp.queryItems = [\n            .init(name: "search", value: query),\n            .init(name: "limit", value: "\\(limit)"),\n            .init(name: "filter", value: "gguf"),\n            .init(name: "sort", value: "downloads"),\n            .init(name: "direction", value: "-1")\n        ]\n        let (data, resp) = try await URLSession.shared.data(from: comp.url!)\n        guard (resp as? HTTPURLResponse)?.statusCode == 200 else { throw URLError(.badServerResponse) }\n        return try JSONDecoder().decode([Repo].self, from: data)\n    }\n\n    /// GGUF files in a repo\'s main branch; split shards (00001-of-...) excluded.\n    static func ggufFiles(_ repoId: String) async throws -> [(path: String, size: Int64, url: URL)] {\n        let u = URL(string: "https://huggingface.co/api/models/\\(repoId)/tree/main")!\n        let (data, resp) = try await URLSession.shared.data(from: u)\n        guard (resp as? HTTPURLResponse)?.statusCode == 200 else { throw URLError(.badServerResponse) }\n        let nodes = try JSONDecoder().decode([TreeNode].self, from: data)\n        return nodes.filter { $0.path.hasSuffix(".gguf") && !$0.path.contains("-of-") }\n            .map { n in\n                let enc = n.path.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? n.path\n                return (n.path, n.size ?? 0,\n                        URL(string: "https://huggingface.co/\\(repoId)/resolve/main/\\(enc)")!)\n            }\n    }\n}\n', 'PersonaChat/LLMEngine.swift': 'import Foundation\nimport llama\n\n/// Single-model engine wrapping the llama.cpp C API. CPU-only by default.\n/// `generate` blocks — call it from a background thread/queue.\nfinal class LLMEngine: @unchecked Sendable {\n    static let shared = LLMEngine()\n\n    private var model: OpaquePointer?\n    private var ctx: OpaquePointer?\n    private var vocab: OpaquePointer?\n    private(set) var nCtx: Int32 = 4096\n    private let lock = NSLock()\n    private var stopFlag = false\n\n    private(set) var isLoaded = false\n\n    func loadModel(path: String, nCtx: Int32 = 4096, nThreads: Int32 = 4) -> Bool {\n        lock.lock(); defer { lock.unlock() }\n        freeLocked()\n        llama_backend_init()\n        var mp = llama_model_default_params()\n        mp.n_gpu_layers = 0 // raise only with a Metal-enabled build\n        guard let m = llama_model_load_from_file(path, mp) else { return false }\n        var cp = llama_context_default_params()\n        cp.n_ctx = UInt32(nCtx)\n        cp.n_threads = UInt32(nThreads)\n        cp.n_threads_batch = UInt32(nThreads)\n        cp.flash_attn_type = LLAMA_FLASH_ATTN_TYPE_ENABLED\n        guard let c = llama_init_from_model(m, cp) else {\n            llama_model_free(m); return false\n        }\n        model = m; ctx = c; vocab = llama_model_get_vocab(m)\n        self.nCtx = nCtx; isLoaded = true\n        return true\n    }\n\n    func unload() { lock.lock(); defer { lock.unlock() }; freeLocked() }\n\n    func stop() { stopFlag = true }\n\n    private func freeLocked() {\n        if let c = ctx { llama_free(c); ctx = nil }\n        if let m = model { llama_model_free(m); model = nil }\n        vocab = nil; isLoaded = false\n    }\n\n    /// Model\'s built-in chat template via metadata; "" means caller should fall back.\n    func applyChatTemplate(_ messages: [(role: String, content: String)], addAssistant: Bool) -> String {\n        lock.lock(); defer { lock.unlock() }\n        guard let model else { return "" }\n        var tmpl = [CChar](repeating: 0, count: 8192)\n        let nTmpl = llama_model_meta_val_str(model, "tokenizer.chat_template", &tmpl, Int32(tmpl.count))\n        guard nTmpl > 0 else { return "" }\n\n        let rolePtrs = messages.map { strdup($0.role) }\n        let contentPtrs = messages.map { strdup($0.content) }\n        defer { rolePtrs.forEach { free($0) }; contentPtrs.forEach { free($0) } }\n        var chat = (0..<messages.count).map {\n            llama_chat_message(role: rolePtrs[$0], content: contentPtrs[$0])\n        }\n        let needed = tmpl.withUnsafeBufferPointer { bp in\n            chat.withUnsafeMutableBufferPointer { cp in\n                llama_chat_apply_template(bp.baseAddress, cp.baseAddress, cp.count, addAssistant, nil, 0)\n            }\n        }\n        guard needed > 0 else { return "" }\n        var buf = [CChar](repeating: 0, count: Int(needed) + 8)\n        tmpl.withUnsafeBufferPointer { bp in\n            chat.withUnsafeMutableBufferPointer { cp in\n                _ = llama_chat_apply_template(bp.baseAddress, cp.baseAddress, cp.count, addAssistant, &buf, Int32(buf.count))\n            }\n        }\n        return String(cString: buf)\n    }\n\n    /// Token-streaming generation. Blocks the caller\'s thread.\n    @discardableResult\n    func generate(prompt: String, temp: Float = 0.8, topP: Float = 0.95,\n                  nPredict: Int32 = 512, seed: UInt32? = nil,\n                  onToken: (String) -> Void) -> String {\n        lock.lock(); defer { lock.unlock() }\n        guard let ctx, let vocab else { return "" }\n        stopFlag = false\n\n        let nMax = Int(nCtx) - 8\n        var tokens = [llama_token](repeating: 0, count: nMax + 8)\n        var nPrompt = llama_tokenize(vocab, prompt, Int32(prompt.utf8.count),\n                                     &tokens, Int32(tokens.count), true, true)\n        guard nPrompt > 0 else { return "" }\n        if nPrompt > nMax { tokens.removeFirst(nPrompt - nMax); nPrompt = Int32(nMax) }\n\n        let tokPtr = UnsafeMutablePointer<llama_token>.allocate(capacity: tokens.count)\n        tokPtr.initialize(from: tokens, count: tokens.count)\n        defer { tokPtr.deallocate() }\n\n        var batch = llama_batch_get_one(tokPtr, nPrompt)\n        guard llama_decode(ctx, batch) == 0 else { return "" }\n\n        let sp = llama_sampler_chain_init(llama_sampler_chain_default_params())\n        llama_sampler_chain_add(sp, llama_sampler_init_top_p(topP, 1))\n        llama_sampler_chain_add(sp, llama_sampler_init_temp(temp <= 0 ? 0.05 : temp))\n        llama_sampler_chain_add(sp, llama_sampler_init_dist(seed ?? UInt32.random(in: 0...UInt32.max)))\n        defer { llama_sampler_free(sp) }\n\n        var out = ""\n        let nKeep: Int32 = 256\n        var i: Int32 = 0\n        while i < nPredict && !stopFlag {\n            let tok = llama_sampler_sample(sp, ctx, -1)\n            if llama_vocab_is_eog(vocab, tok) { break }\n            var piece = [CChar](repeating: 0, count: 256)\n            let n = llama_token_to_piece(vocab, tok, &piece, Int32(piece.count), false, true)\n            if n > 0 {\n                let s = String(cString: piece)\n                out += s\n                onToken(s)\n            }\n            tokPtr.pointee = tok\n            batch = llama_batch_get_one(tokPtr, 1)\n            if llama_decode(ctx, batch) != 0 { break }\n            if llama_get_kv_cache_used_cells(ctx) >= nCtx - 4 {\n                llama_kv_cache_seq_rm(ctx, 0, 1, nKeep)\n                llama_kv_cache_seq_add(ctx, 0, nKeep, -1, -1)\n            }\n            i += 1\n        }\n        return out\n    }\n}\n', 'PersonaChat/Models.swift': 'import Foundation\n\nstruct Character: Codable, Identifiable, Equatable {\n    var id: UUID = UUID()\n    var name: String = "New Character"\n    var avatar: String = "\\u{1F9D9}"\n    var persona: String = ""\n    var scenario: String = ""\n    var greeting: String = ""\n    var exampleDialogue: String = ""\n    var createdAt: Date = Date()\n}\n\nstruct ChatMessage: Codable, Equatable, Identifiable {\n    var id: UUID = UUID()\n    var role: String   // "system" | "user" | "assistant"\n    var content: String\n    var ts: Date = Date()\n}\n\nenum StorePaths {\n    static var docs: URL {\n        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]\n    }\n    static func chatFile(_ id: UUID) -> URL { docs.appendingPathComponent("chat_\\(id.uuidString).json") }\n    static var charactersFile: URL { docs.appendingPathComponent("characters.json") }\n    static func ggufs() -> [URL] {\n        (try? FileManager.default.contentsOfDirectory(at: docs, includingPropertiesForKeys: nil))\n            ?.filter { $0.pathExtension == "gguf" }.sorted { $0.lastPathComponent < $1.lastPathComponent } ?? []\n    }\n}\n', 'PersonaChat/ModelsView.swift': 'import SwiftUI\n\nstruct ModelsView: View {\n    @State private var models: [URL] = ModelFiles.list()\n    @State private var status = ""\n    @State private var urlText = ""\n    @State private var progress: Double?\n    @State private var ctxSize: Double = 4096\n    @State private var busy = false\n    @ObservedObject private var engineBox = EngineBox()\n\n    // Hugging Face browser\n    @State private var query = ""\n    @State private var repos: [HFApi.Repo] = []\n    @State private var selectedRepo: String?\n    @State private var files: [(path: String, size: Int64, url: URL)] = []\n    @State private var searching = false\n\n    var body: some View {\n        Form {\n            Section("Download") {\n                TextField("GGUF download URL (.../resolve/main/file.gguf)", text: $urlText)\n                    .textInputAutocapitalization(.never)\n                    .autocorrectionDisabled()\n                HStack {\n                    Button("Download") { startDownload() }.disabled(busy || urlText.isEmpty)\n                    if let p = progress { ProgressView(value: p).frame(width: 80) }\n                }\n                Text(status).font(.caption).foregroundStyle(.secondary)\n            }\n            Section("Browse Hugging Face (GGUF)") {\n                HStack {\n                    TextField("Search models, e.g. qwen3, llama-3.2", text: $query)\n                        .textInputAutocapitalization(.never).autocorrectionDisabled()\n                    Button(searching ? "..." : "Search") { search() }\n                        .disabled(searching || query.isEmpty)\n                }\n                ForEach(repos) { r in\n                    VStack(alignment: .leading, spacing: 4) {\n                        HStack {\n                            Text(r.displayName).font(.headline)\n                            Spacer()\n                            Text("\\((r.downloads ?? 0).formatted()) dl · \\(r.likes ?? 0) likes")\n                                .font(.caption).foregroundStyle(.secondary)\n                        }\n                        .contentShape(Rectangle())\n                        .onTapGesture { pick(r) }\n                        if selectedRepo == r.id {\n                            ForEach(files, id: \\.path) { f in\n                                HStack {\n                                    VStack(alignment: .leading) {\n                                        Text(f.path.components(separatedBy: "/").last ?? f.path)\n                                            .font(.caption).lineLimit(1)\n                                        Text(String(format: "%.2f GB", Double(f.size) / 1e9))\n                                            .font(.caption2).foregroundStyle(.secondary)\n                                    }\n                                    Spacer()\n                                    Button("Get") { downloadFile(f.url) }\n                                        .disabled(progress != nil)\n                                }\n                            }\n                        }\n                    }\n                }\n            }\n            Section("Context: \\(Int(ctxSize)) tokens") {\n                Slider(value: $ctxSize, in: 2048...16384, step: 2048)\n            }\n            Section("On-device models (Documents)") {\n                ForEach(models, id: \\.self) { f in\n                    HStack {\n                        VStack(alignment: .leading) {\n                            Text(f.lastPathComponent)\n                            Text(String(format: "%.1f MB", Double(fileSize(f)) / 1e6))\n                                .font(.caption).foregroundStyle(.secondary)\n                        }\n                        Spacer()\n                        if LLMEngine.shared.isLoaded {\n                            Button("Unload") { LLMEngine.shared.unload(); engineBox.tick() }\n                                .buttonStyle(.bordered)\n                        } else {\n                            Button("Load") { load(f) }.buttonStyle(.borderedProminent).disabled(busy)\n                        }\n                    }\n                }\n                Button("Rescan") { models = ModelFiles.list() }\n            }\n            if LLMEngine.shared.isLoaded {\n                Label("Model loaded", systemImage: "checkmark.circle").foregroundStyle(.green)\n            }\n        }\n        .navigationTitle("Local model")\n    }\n\n    private func fileSize(_ u: URL) -> UInt64 {\n        let attrs = try? FileManager.default.attributesOfItem(atPath: u.path)\n        return (attrs?[.size] as? UInt64) ?? 0\n    }\n\n    private func search() {\n        searching = true\n        Task {\n            do { repos = try await HFApi.search(query) }\n            catch { repos = []; status = "Search failed: \\(error.localizedDescription)" }\n            searching = false\n        }\n    }\n\n    private func pick(_ r: HFApi.Repo) {\n        selectedRepo = r.id\n        Task {\n            do { files = try await HFApi.ggufFiles(r.id) }\n            catch { files = []; status = "Failed to list files" }\n        }\n    }\n\n    private func downloadFile(_ url: URL) {\n        busy = true\n        let dest = ModelFiles.newDownloadURL(for: url)\n        Task {\n            do {\n                try await DownloadManager.download(url: url, dest: dest) { done, total in\n                    Task { @MainActor in\n                        status = String(format: "Downloading %.1f MB", Double(done) / 1e6)\n                        progress = (total != nil && total! > 0) ? Double(done) / Double(total!) : nil\n                    }\n                }\n                status = "Saved \\(dest.lastPathComponent)"; progress = nil; busy = false\n                models = ModelFiles.list()\n            } catch {\n                status = "Download failed: \\(error.localizedDescription)"; progress = nil; busy = false\n            }\n        }\n    }\n\n    private func load(_ f: URL) {\n        busy = true; status = "Loading \\(f.lastPathComponent)..."\n        let nCtx = Int32(ctxSize)\n        DispatchQueue.global().async {\n            let ok = LLMEngine.shared.loadModel(path: f.path, nCtx: nCtx)\n            DispatchQueue.main.async {\n                busy = false\n                status = ok ? "Loaded \\(f.lastPathComponent)" : "Failed to load"\n                engineBox.tick()\n            }\n        }\n    }\n\n    private func startDownload() {\n        guard let url = URL(string: urlText) else { status = "Bad URL"; return }\n        busy = true\n        let dest = ModelFiles.newDownloadURL(for: url)\n        Task {\n            do {\n                try await DownloadManager.download(url: url, dest: dest) { done, total in\n                    Task { @MainActor in\n                        status = String(format: "Downloading %.1f MB", Double(done) / 1e6)\n                        progress = (total != nil && total! > 0) ? Double(done) / Double(total!) : nil\n                    }\n                }\n                status = "Saved \\(dest.lastPathComponent)"; progress = nil; busy = false\n                models = ModelFiles.list()\n            } catch {\n                status = "Download failed: \\(error.localizedDescription)"\n                progress = nil; busy = false\n            }\n        }\n    }\n}\n\n/// Tiny observable to poke SwiftUI after engine state changes.\nfinal class EngineBox: ObservableObject { @Published var n = 0; func tick() { n += 1 } }\n', 'PersonaChat/PersonaChatApp.swift': 'import SwiftUI\n\n@main\nstruct PersonaChatApp: App {\n    init() { CharacterStore.shared.load() }\n    var body: some Scene {\n        WindowGroup {\n            TabView {\n                NavigationStack { CharactersView() }\n                    .tabItem { Label("Characters", systemImage: "person.2") }\n                NavigationStack { ModelsView() }\n                    .tabItem { Label("Model", systemImage: "cpu") }\n            }\n        }\n    }\n}\n', 'PersonaChat/PromptBuilder.swift': 'import Foundation\n\nenum PromptBuilder {\n    static func systemPrompt(_ c: Character) -> String {\n        var s = "You are \\(c.name), a fictional character in a roleplay chat.\\n"\n        if !c.persona.isEmpty { s += "Personality and background:\\n\\(c.persona)\\n" }\n        if !c.scenario.isEmpty { s += "Current scenario/setting:\\n\\(c.scenario)\\n" }\n        if !c.exampleDialogue.isEmpty { s += "Example dialogue (match this voice):\\n\\(c.exampleDialogue)\\n" }\n        s += "\\nRules: Always stay fully in character as \\(c.name). Never break character, "\n        s += "never mention being an AI or a language model. Write as \\(c.name) in first person. "\n        s += "Keep replies conversational (a few sentences unless the scene calls for more)."\n        return s\n    }\n\n    /// Model template when available, plain-format fallback otherwise.\n    static func buildPrompt(c: Character, history: [ChatMessage]) -> String {\n        var msgs: [(role: String, content: String)] = [("system", systemPrompt(c))]\n        msgs.append(contentsOf: history.map { ($0.role, $0.content) })\n        let templated = LLMEngine.shared.applyChatTemplate(msgs, addAssistant: true)\n        if !templated.isEmpty { return templated }\n        var s = "System: \\(systemPrompt(c))\\n\\n"\n        for m in history { s += "\\(m.role == "user" ? "User" : c.name): \\(m.content)\\n\\n" }\n        s += "\\(c.name): "\n        return s\n    }\n\n    static func trimmed(_ history: [ChatMessage], maxChars: Int = 6000) -> [ChatMessage] {\n        var out: [ChatMessage] = []\n        var used = 0\n        for m in history.reversed() {\n            if used + m.content.count > maxChars { break }\n            out.append(m); used += m.content.count\n        }\n        return out.reversed()\n    }\n}\n', 'PersonaChat/Stores.swift': 'import Foundation\nimport Combine\n\nfinal class CharacterStore: ObservableObject {\n    static let shared = CharacterStore()\n    @Published var characters: [Character] = []\n    private let encoder: JSONEncoder = { let e = JSONEncoder(); e.outputFormatting = .prettyPrinted; return e }()\n\n    func load() {\n        guard let data = try? Data(contentsOf: StorePaths.charactersFile) else { return }\n        characters = (try? JSONDecoder().decode([Character].self, from: data)) ?? []\n    }\n    private func persist() {\n        guard let data = try? encoder.encode(characters) else { return }\n        try? data.write(to: StorePaths.charactersFile)\n    }\n    @discardableResult\n    func newCharacter() -> Character {\n        let c = Character(); characters.append(c); persist(); return c\n    }\n    func upsert(_ c: Character) {\n        if let i = characters.firstIndex(where: { $0.id == c.id }) { characters[i] = c }\n        else { characters.append(c) }\n        persist()\n    }\n    func delete(_ id: UUID) {\n        characters.removeAll { $0.id == id }\n        persist()\n        try? FileManager.default.removeItem(at: StorePaths.chatFile(id))\n    }\n\n    func loadMessages(_ id: UUID) -> [ChatMessage] {\n        guard let data = try? Data(contentsOf: StorePaths.chatFile(id)) else { return [] }\n        return (try? JSONDecoder().decode([ChatMessage].self, from: data)) ?? []\n    }\n    func saveMessages(_ id: UUID, _ msgs: [ChatMessage]) {\n        guard let data = try? encoder.encode(msgs) else { return }\n        try? data.write(to: StorePaths.chatFile(id))\n    }\n}\n\nenum ModelFiles {\n    static func list() -> [URL] { StorePaths.ggufs() }\n    static func newDownloadURL(for url: URL) -> URL {\n        let name = url.lastPathComponent.isEmpty ? "model.gguf" : url.lastPathComponent\n        return StorePaths.docs.appendingPathComponent(name)\n    }\n    static func excludeFromBackup(_ url: URL) {\n        var u = url\n        var v = URLResourceValues()\n        v.isExcludedFromBackup = true\n        try? u.setResourceValues(v)\n    }\n}\n', 'scripts/fetch_llama_cpp.sh': '#!/usr/bin/env bash\n# Run from the iOS project root. Clones llama.cpp (which ships a Package.swift)\n# into Packages/llama.cpp so XcodeGen can wire it in as a local Swift package.\nset -e\nmkdir -p Packages\ngit clone --depth 1 https://github.com/ggml-org/llama.cpp Packages/llama.cpp\necho "Done. Open Package.swift inside Packages/llama.cpp if you need to check product names."\n'}

NEXT = {
  "android": """
Android next steps:
  1. Open in Android Studio (SDK 34, NDK, CMake 3.22.1)
  2. Run scripts/fetch_llama_cpp.sh to vendor llama.cpp into app/src/main/cpp/
  3. Sync Gradle, build, run on an ARM64 device
""",
  "ios": """
iOS next steps:
  1. macOS + Xcode 15+, install XcodeGen: brew install xcodegen
  2. Run scripts/fetch_llama_cpp.sh (clones llama.cpp into Packages/, ships Package.swift)
  3. xcodegen generate
  4. open PersonaChat.xcodeproj, set signing team, run on a real device
""",
}

def write_tree(files, outdir):
    for rel, content in files.items():
        dest = os.path.join(outdir, rel)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "w", encoding="utf-8") as f:
            f.write(content)
    sh = os.path.join(outdir, "scripts", "fetch_llama_cpp.sh")
    if os.path.exists(sh):
        os.chmod(sh, 0o755)

def main():
    ap = argparse.ArgumentParser(description="Generate the PersonaChat project tree.")
    ap.add_argument("--platform", choices=["android", "ios", "both"], required=True)
    ap.add_argument("--out", default=".")
    args = ap.parse_args()
    targets = [("android", ANDROID_FILES, "PersonaChat")] if args.platform in ("android", "both") else []
    targets += [("ios", IOS_FILES, "PersonaChat-iOS")] if args.platform in ("ios", "both") else []
    for name, files, d in targets:
        o = os.path.join(args.out, d) if args.platform == "both" else args.out
        write_tree(files, o)
        print(f"[ok] generated {name} -> {o} ({len(files)} files)")
        print(NEXT[name])

if __name__ == "__main__":
    main()
